  Lemma pm_v3_pb : forall (vc : vec_consts), vec32_push_back_stmt SEGS Ly.L MI ST vc -> vc_stack vc = 64 ->
    forall (w : pmw MI ST) c0 K (fx : FPState) A M model c R (src x ret : Z),
    PMS w c0 K -> PMX w A M model c -> c_tr c = [] -> pm_bud (w_n w) c ->
    cregs w R ret -> getr R 10%bv = Z_to_bv 64 (w_p w + O_V3) -> getr R 11%bv = Z_to_bv 64 src ->
    fld SEGS M src 4 x -> 0 <= x < 2 ^ 32 -> w_sp w <= src -> src + 4 <= w_sp0 w - 104 ->
    (Zlen (t3b (c_v3 c)) = t3c (c_v3 c) -> 4 * vgrow (t3c (c_v3 c)) <= 2 ^ 26) ->
    (forall A' R' M' model' (b' cap' : Z),
        PMX w A' M' model' (set_v3 c (b', t3b (c_v3 c) ++ [x], cap')) -> pm_bud (w_n w) (set_v3 c (b', t3b (c_v3 c) ++ [x], cap')) ->
        kept R R' -> CRep.agree_on (fun a => w_sp w <= a < w_sp0 w) M M' ->
        srealizes SEGS (cfg fx R' ret M' model') K) ->
    srealizes SEGS (cfg fx R (vc_entry vc) M model) K.
