  Lemma pm_find_gen : forall (F o : Z) (prj : pmc -> Z * Z * list (Z * (Z * Z))),
    find_stmt SEGS Ly.L MI F 24 Z (nval24 SEGS) ->
    (forall (w : pmw MI ST) A M model c, PMX w A M model c -> umapx MI 24 (nval24 SEGS) A M (w_p w + o) (t3a (prj c)) (t3b (prj c)) (t3c (prj c))) ->
    forall (w : pmw MI ST) A M model c (fx : FPState) R (keyp key ret : Z) K,
    PMX w A M model c ->
    getr R 10%bv = Z_to_bv 64 (w_p w + o) -> getr R 11%bv = Z_to_bv 64 keyp ->
    cell4 SEGS M keyp key -> 0 < keyp -> keyp + 4 <= 2 ^ 47 ->
    getr R 1%bv = Z_to_bv 64 ret -> ret_ok (Z_to_bv 64 ret) ->
    (forall R' (p : Z), kept R R' -> getr R' 10%bv = Z_to_bv 64 p ->
        (p = 0 \/ (0 < p /\ p + 24 <= 2 ^ 47 /\ p mod 16 = 0 /\ exists v, In (p, (key, v)) (t3c (prj c)) /\ cell4 SEGS M (p + 20) v)) ->
        srealizes SEGS (cfg fx R' ret M model) K) ->
    srealizes SEGS (cfg fx R F M model) K.
Proof using AC MI ST.
